const items = $input.all();
let allArticles = '';

for (const item of items) {
  const raw = item.json.data || item.json.body || item.json.content || '';
  if (!raw) continue;

  // Extract <item> blocks from RSS XML
  const matches = raw.match(/<item>([\s\S]*?)<\/item>/g) || [];

  for (const entry of matches.slice(0, 5)) { // 5 articles per source
    const title   = (entry.match(/<title><!\[CDATA\[(.*?)\]\]><\/title>/)   || entry.match(/<title>(.*?)<\/title>/))?.[1]   || '';
    const desc    = (entry.match(/<description><!\[CDATA\[(.*?)\]\]><\/description>/) || entry.match(/<description>(.*?)<\/description>/))?.[1] || '';
    const link    = (entry.match(/<link>(.*?)<\/link>/))?.[1] || '';
    const pubDate = (entry.match(/<pubDate>(.*?)<\/pubDate>/))?.[1] || '';

    if (title) {
      allArticles += `TITLE: ${title}\n`;
      allArticles += `DATE: ${pubDate}\n`;
      allArticles += `SUMMARY: ${desc.replace(/<[^>]+>/g, '').slice(0, 200)}\n`;
      allArticles += `---\n`;
    }
  }
}

const competitors = $('Load Competitors').all().map(r => {
  const f = r.json.fields;
  return `${f.Competitor}: ${f.Service}, Price: ${f.Price}, Delivery: ${f['Delivery Speed']}, Unique: ${f['Unique Feature']}`;
}).join('\n');

const mergedData = `COMPETITOR DATA:\n${competitors}\n\nLATEST NEWS:\n${allArticles}`;

return [{ json: { mergedData } }];

const aiText = $('Groq AI Analysis').first().json.choices[0].message.content;
const today = new Date().toLocaleDateString('en-PK', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

// ── Markdown → HTML converter ──────────────────────────────────────────────
function markdownToHtml(text) {
  if (!text) return '';
  const lines = text.split('\n');
  let html = '';
  let inTable = false;
  let tableRows = [];

  const flushTable = () => {
    if (!tableRows.length) return;
    let t = '<table style="width:100%;border-collapse:collapse;font-size:13px;margin:10px 0;">';
    tableRows.forEach((row, i) => {
      const cells = row.split('|').map(c => c.trim()).filter(c => c);
      if (!cells.length) return;
      const tag = i === 0 ? 'th' : 'td';
      const bg  = i === 0 ? '#1e3a5f' : (i % 2 === 0 ? '#f8fafc' : '#ffffff');
      const col = i === 0 ? '#ffffff' : '#000000';
      const fw  = i === 0 ? '600' : '400';
      t += '<tr>' + cells.map(c =>
        `<${tag} style="padding:10px 12px;border:1px solid #dde4ed;background:${bg};color:${col};font-weight:${fw};text-align:left;">${c}</${tag}>`
      ).join('') + '</tr>';
    });
    t += '</table>';
    html += t;
    tableRows = [];
    inTable = false;
  };

  for (const raw of lines) {
    const line = raw.trim();

    // separator row (---|---) — skip
    if (/^\|?[\s\-|:]+\|?$/.test(line) && line.includes('-')) continue;

    // table row
    if (line.startsWith('|') && line.endsWith('|')) {
      inTable = true;
      tableRows.push(line.slice(1, -1));
      continue;
    }

    // flush table when non-table line encountered
    if (inTable) flushTable();

    if (!line) { html += '<br>'; continue; }

    // headings
    if (/^#{1,3}\s/.test(line)) {
      const lvl = line.match(/^#+/)[0].length;
      const txt = line.replace(/^#+\s+/, '');
      const sz  = lvl === 1 ? '18px' : lvl === 2 ? '15px' : '14px';
      html += `<p style="font-size:${sz};font-weight:700;color:#1e3a5f;margin:14px 0 6px;">${txt}</p>`;
      continue;
    }

    // bullet points
    if (/^[-*•]\s/.test(line)) {
      let item = line.replace(/^[-*•]\s+/, '');
      item = item.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
      html += `<div style="display:flex;gap:8px;margin:5px 0;font-size:14px;line-height:1.7;">
        <span style="color:#2d6a9f;font-weight:700;flex-shrink:0;">•</span>
        <span>${item}</span></div>`;
      continue;
    }

    // numbered list
    if (/^\d+\.\s/.test(line)) {
      const num = line.match(/^\d+/)[0];
      let item  = line.replace(/^\d+\.\s+/, '');
      item = item.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
      html += `<div style="display:flex;gap:8px;margin:5px 0;font-size:14px;line-height:1.7;">
        <span style="color:#2d6a9f;font-weight:700;flex-shrink:0;min-width:18px;">${num}.</span>
        <span>${item}</span></div>`;
      continue;
    }

    // normal paragraph — convert inline bold
    let para = line.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
    html += `<p style="font-size:14px;line-height:1.8;margin:5px 0;color:#000000;">${para}</p>`;
  }

  if (inTable) flushTable();
  return html;
}
// ──────────────────────────────────────────────────────────────────────────

// Split AI response into sections
const sections = { intelligence: '', gaps: '', action: '', advantage: '' };
const lines = aiText.split('\n');
let current = '';

for (const line of lines) {
  if (line.includes('MARKET INTELLIGENCE'))  { current = 'intelligence'; continue; }
  if (line.includes('OPPORTUNITY GAP'))       { current = 'gaps';         continue; }
  if (line.includes('SUGGESTED ACTION'))      { current = 'action';       continue; }
  if (line.includes('COMPETITIVE ADVANTAGE')) { current = 'advantage';    continue; }
  if (current && line.trim()) sections[current] += line + '\n';
}

// Convert each section
const intel     = markdownToHtml(sections.intelligence || aiText);
const gaps      = markdownToHtml(sections.gaps);
const action    = markdownToHtml(sections.action);
const advantage = markdownToHtml(sections.advantage);

