      <div class="stat-card"><div class="stat-label">Frequency</div><div class="stat-value">Daily</div></div>
      <div class="stat-card"><div class="stat-label">Market</div><div class="stat-value">Pakistan</div></div>
    </div>
    <div class="section">
      <div class="section-header">
        <div class="section-icon icon-blue">📊</div>
        <div><div class="section-title">Market Intelligence</div><div class="section-subtitle">What is happening in the market right now</div></div>
      </div>
      ${intel}
    </div>
    <div class="section">
      <div class="section-header">
