        <div class="section-icon icon-purple">⚡</div>
        <div><div class="section-title">Competitive Advantage</div><div class="section-subtitle">How to win against existing players</div></div>
      </div>
      <div class="advantage-box">${advantage}</div>
    </div>
  </div>
  <div class="footer">
