    <div class="powered">Groq AI <span class="dots">•</span> Airtable <span class="dots">•</span> ARY News <span class="dots">•</span> n8n Automation</div>
  </div>
</div>
</body>
</html>`;

return [{ json: { reportText: aiText, reportHTML: htmlReport, reportDate: today } }];

